"""Test edge cases for the HTML stripping fix."""

import markdown
from mkdocs.structure.pages import _ExtractTitleTreeprocessor
from xml.etree import ElementTree as etree


def test_edge_cases():
    """Test edge cases to ensure robustness."""

    class MockMd:
        def __init__(self):
            self.stashed_html = {}

    test_cases = [
        # Self-closing tags
        {
            'html': '<div><h1>Title<br/>Break</h1></div>',
            'expected': 'TitleBreak',
            'description': 'Self-closing br tag'
        },
        # Nested tags
        {
            'html': '<div><h1>Title <span>nested <b>bold</b> text</span></h1></div>',
            'expected': 'Title nested bold text',
            'description': 'Nested HTML tags'
        },
        # Attributes with quotes
        {
            'html': '<div><h1>Title <span class="test" id=\'item\'>content</span></h1></div>',
            'expected': 'Title content',
            'description': 'Tags with quoted attributes'
        },
        # Malformed HTML (should still work reasonably)
        {
            'html': '<div><h1>Title <span>unclosed content</h1></div>',
            'expected': 'Title unclosed content',  # itertext handles this
            'description': 'Unclosed tags'
        },
        # Empty tags
        {
            'html': '<div><h1>Title <span></span> Content</h1></div>',
            'expected': 'Title  Content',
            'description': 'Empty tags'
        },
        # Tags with numbers and special chars in attributes
        {
            'html': '<div><h1>Title <span data-id="123" class="test-class_1">Content</span></h1></div>',
            'expected': 'Title Content',
            'description': 'Complex attributes'
        }
    ]

    print("Testing edge cases for HTML stripping...")
    print("=" * 50)

    for i, test_case in enumerate(test_cases, 1):
        print(f"\n{i}. {test_case['description']}")
        print(f"   HTML: {test_case['html']}")

        root = etree.fromstring(test_case['html'])
        extract_title_ext = _ExtractTitleTreeprocessor()
        extract_title_ext.md = MockMd()
        extract_title_ext.run(root)

        result = extract_title_ext.title
        expected = test_case['expected']

        print(f"   Result: {result!r}")
        print(f"   Expected: {expected!r}")

        if result == expected:
            print("   ✅ PASS")
        else:
            print("   ❌ FAIL")


if __name__ == "__main__":
    test_edge_cases()"}

